 r=requests.get(u,timeout=15); print('HTTP',r.status_code); print(r.text[:1000])
 if r.ok:
  cids=r.json().get('IdentifierList',{}).get(' CID',r.json().get('IdentifierList',{}).get('CID',[])); print('CIDs',cids)
except Exception as e: print(type(e).__name__,str(e))
